import re
def parse_grid_block(txt, header):
    p=txt.find(header)
    seg=txt[p:txt.find('\n\n', p) if txt.find('\n\n',p)!=-1 else len(txt)]
    rows=[]
    for line in seg.splitlines()[1:]:
        if re.fullmatch(r'[\d ]+', line.strip()) and line.strip():
            rows.append([int(x) for x in line.split()])
        else: break
    return np.array(rows)

