def npl(i_):
    pts=[(int(p[0]),int(p[1])) for p in np.argwhere(i_==1)]
    out=np.asarray(i_).copy(); used=set(); lines=[]
    cand=[]
    for x in range(len(pts)):
        for y in range(x+1,len(pts)):
            if pts[x][0]==pts[y][0] or pts[x][1]==pts[y][1]:
                cand.append((abs(pts[x][0]-pts[y][0])+abs(pts[x][1]-pts[y][1]),x,y))
    for dd,x,y in sorted(cand):
        if x in used or y in used: continue
        used.add(x); used.add(y)
        if pts[x][0]==pts[y][0]:
            rr=pts[x][0]; out[rr,:]=1; lines.append(('r',rr))
        else:
            c2=pts[x][1]; out[:,c2]=1; lines.append(('c',c2))
    labt,n=ndimage.label(np.asarray(i_)==2)
    for kk in range(1,n+1):
        ys,xs=np.where(labt==kk)
        hit=any((t=='r' and ys.min()<=v<=ys.max()) or (t=='c' and xs.min()<=v<=xs.max()) for t,v in lines)
